arguments.command:
mkdir -p /filesystem/work && cd /filesystem/final_batch4__electrical_task8_electrical_specs__blind && cat > /filesystem/work/ifc_feeders.py << 'EOF'
import ifcopenshell, ifcopenshell.util.placement as up, ifcopenshell.util.element as ue
import numpy as np, re, collections, json
f = ifcopenshell.open('50_bim/BLDG4410-E_RevC.ifc')
MM2FT = 1/304.8
segs = f.by_type('IfcCableCarrierSegment')
print('segments', len(segs))
# group membership
grp = {}
for rel in f.by_type('IfcRelAssignsToGroup'):
    for o in rel.RelatedObjects:
        grp.setdefault(o.id(), []).append(rel.RelatingGroup.Name)
rows = []
for s in segs:
    psets = ue.get_psets(s)
    ref = None; status=None; nd=None
    for pn, pv in psets.items():
        if 'Reference' in pv: ref = pv['Reference']
        if 'Status' in pv: status = pv['Status']
        if 'NominalDiameter' in pv: nd = pv['NominalDiameter']
    M = up.get_local_placement(s.ObjectPlacement)
    # axis representation
    pts_all = []
    L = 0.0
    for rep in s.Representation.Representations:
        if rep.RepresentationIdentifier == 'Axis':
            for it in rep.Items:
                pts = [np.array(list(p.Coordinates) + [0.0]*(3-len(p.Coordinates))) for p in it.Points]
                wp = [ (M @ np.append(p,1.0))[:3] for p in pts]
                pts_all.append(wp)
                for a,b in zip(wp[:-1], wp[1:]):
                    L += np.linalg.norm(b-a)
    body_r = None
    for rep in s.Representation.Representations:
        if rep.RepresentationIdentifier == 'Body':
            for it in rep.Items:
                if it.is_a('IfcSweptDiskSolid'): body_r = it.Radius
    rows.append(dict(id=s.id(), name=s.Name, objtype=s.ObjectType, ref=ref, status=status, nd=nd, grp=grp.get(s.id()), L_mm=L, body_r=body_r, pts=[ [list(map(lambda v: round(float(v),1), p)) for p in wp] for wp in pts_all]))
for r in rows:
    print(r['id'], r['name'], r['objtype'], 'ref=',r['ref'], r['status'], 'nd=',r['nd'], 'grp=',r['grp'], 'L=%.1f mm'%r['L_mm'], 'r=',r['body_r'], r['pts'])
json.dump(rows, open('/filesystem/work/segs.json','w'), indent=1)
EOF
python3 /filesystem/work/ifc_feeders.py 2>&1 | head -200

